    var root;
    var effects;
    var progressEffect;
    var progressProperty;
    var fillGroup;
    var fillContents;
    var fillPath;
    var fillSize;
    var fillPosition;
    var glowCount = 0;
    var expressionCount = 0;
    var expressionErrors = [];
    var layerIndex;
    var effectIndex;

    function valueText(value) {
        var parts = [];
        var index;

        if (value instanceof Array) {
            for (index = 0; index < value.length; index += 1) {
                parts.push(Number(value[index]).toFixed(2));
            }
            return parts.join(",");
        }
        return String(value);
    }

    function inspectExpressions(group, path) {
        var index;
        var child;
        var childPath;

        if (!group || group.numProperties === undefined) {
            return;
        }

        for (index = 1; index <= group.numProperties; index += 1) {
            child = group.property(index);
            childPath = path + "/" + child.name;

            if (child.propertyType === PropertyType.PROPERTY) {
                if (child.canSetExpression && child.expressionEnabled) {
                    expressionCount += 1;
                    if (child.expressionError && child.expressionError !== "") {
                        expressionErrors.push(childPath + ": " + child.expressionError);
                    }
                }
            } else {
                inspectExpressions(child, childPath);
            }
        }
    }

