/* Read-only inventory of registered effects and already-applied parameters. */
(function () {
    if (!app.project) { throw new Error("No After Effects project"); }
    var lines = ["AE_PLUGIN_CATALOG_V1", "AE\t" + app.version];
    var effects = app.effects;
    var seen = {};
    var i, j, k, comp, layer, parade, effect;
    function clean(value) { return String(value).replace(/[\t\r\n]/g, " "); }
    function walk(group, path, depth) {
        var n, p, value, range;
        for (n = 1; n <= group.numProperties; n += 1) {
            p = group.property(n);
            if (!p) { continue; }
            range = "";
            value = "";
            if (p.propertyType === PropertyType.PROPERTY) {
                try {
                    if (p.hasMin) { range += "min=" + p.minValue + " "; }
                    if (p.hasMax) { range += "max=" + p.maxValue; }
                    if (p.propertyValueType !== PropertyValueType.CUSTOM_VALUE &&
                            p.propertyValueType !== PropertyValueType.NO_VALUE) {
                        value = clean(p.value);
                    }
                } catch (valueError) { value = "unavailable"; }
            }
            lines.push("PARAM\t" + clean(path) + "\t" + clean(p.matchName) + "\t" +
                clean(p.name) + "\t" + p.propertyType + "\t" + range + "\t" + value);
            if (p.propertyType !== PropertyType.PROPERTY && depth < 8) {
                walk(p, path + "/" + p.matchName, depth + 1);
            }
        }
    }
    for (i = 0; i < effects.length; i += 1) {
        lines.push("EFFECT\t" + clean(effects[i].displayName) + "\t" +
            clean(effects[i].matchName) + "\t" + clean(effects[i].category) + "\t" +
            clean(effects[i].version));
    }
    for (i = 1; i <= app.project.numItems; i += 1) {
        comp = app.project.item(i);
        if (!(comp instanceof CompItem)) { continue; }
        for (j = 1; j <= comp.numLayers; j += 1) {
            layer = comp.layer(j);
            parade = layer.property("ADBE Effect Parade");
            if (!parade) { continue; }
            for (k = 1; k <= parade.numProperties; k += 1) {
                effect = parade.property(k);
                if (!effect || seen["$" + effect.matchName]) { continue; }
                seen["$" + effect.matchName] = true;
                lines.push("APPLIED\t" + clean(effect.matchName) + "\t" + clean(effect.name));
                walk(effect, effect.matchName, 0);
            }
        }
    }
    return lines.join("\n");
}());

