    var originalName = destination.name;
    var stamp = String(new Date().getTime());
    var temporary = new File(panelFolder.fsName + "/Codex Bridge.jsx.tmp-" + stamp);
    var backup = new File(panelFolder.fsName + "/Codex Bridge.jsx.bak-" + stamp);
    var sourceData;
    var writtenData;

    if (!source.exists) {
        throw new Error("Workspace panel source not found: " + source.fsName);
    }
    if (!panelFolder.exists) {
        throw new Error("Installed ScriptUI Panels folder not found: " + panelFolder.fsName);
    }
    if (!destination.exists) {
        throw new Error("Installed Codex Bridge panel not found: " + destination.fsName);
    }

    source.encoding = "BINARY";
    if (!source.open("r")) {
        throw new Error("Cannot read workspace panel source: " + source.error);
    }
    try {
        sourceData = source.read();
    } finally {
        source.close();
    }

    temporary.encoding = "BINARY";
    if (!temporary.open("w")) {
        throw new Error("Cannot create temporary panel file: " + temporary.error);
    }
    try {
        temporary.write(sourceData);
    } finally {
        temporary.close();
    }

    temporary.encoding = "BINARY";
    if (!temporary.open("r")) {
        temporary.remove();
        throw new Error("Cannot verify temporary panel file: " + temporary.error);
    }
    try {
        writtenData = temporary.read();
    } finally {
        temporary.close();
    }

    if (writtenData !== sourceData) {
        temporary.remove();
        throw new Error("Temporary panel verification failed");
    }

    if (!destination.rename(backup.name)) {
        temporary.remove();
        throw new Error("Cannot back up installed panel: " + destination.error);
    }

    if (!temporary.rename(originalName)) {
        backup.rename(originalName);
        throw new Error("Cannot publish updated panel: " + temporary.error);
    }

    return "Updated installed panel to workspace version. Backup: " + backup.fsName;
}());

